mapper.select:
select a.code as menu_code, a.name, ifnull(b.use_yn,'N') as use_yn, ifnull(b.c_yn,'N') as c_yn, ifnull(b.r_yn,'N') as r_yn, ifnull(b.d_yn,'N') as d_yn from tb_menu a left outer join tb_menu_auth b on a.code = b.menucode where 1=1
and a.code = #{menu_code}
and b.role_id = #{role_id}

mapper.update:
update tb_menu_auth
   set c_yn = #{c_yn}
      ,r_yn = #{r_yn}
      ,d_yn = #{d_yn}
      ,use_yn = #{use_yn}
      ,update_by = #{updateBy}
      ,update_dt = NOW()
 where 1=1
   and menucode = #{menu_code}
   and role_id = #{role_id}

mapper.delete:
delete 
  from tb_menu_auth
 where 1=1
   and menucode = #{menu_code}
   and role_id = #{role_id}
